# Load demo pair
with open(f"{program_dir}/{task_id}.json") as f:
    data = json.load(f)
demo = data[0]
demo_input = demo['input']
demo_output = demo['output']

print(f"Demo output: {demo_output}")
print(f"Demo input shape: {len(demo_input)}x{len(demo_input[0])}")

# Print demo input rows correctly
print("\nDemo input (first 5 rows):")
for r in range(5):
    row_val = demo_input[r]
    print(f"  Row {r}: {list(row_val)[:10]}...{list(row_val)[-10:]}")

# Count connected components for each value in demo
def count_connected_components(grid):
    if not grid or not grid[0]:
        return {}
    h, w = len(grid), len(grid[0])
    comp_count = {}
    visited = [[False]*w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if not visited[r][c]:
                val = grid[r][c]
                q = [(r, c)]
                visited[r][c] = True
                size = 0
                while q:
                    cr, cc = q.pop()
                    size += 1
                    for nr, nc in [(cr+1,cc), (cr-1,cc), (cr,cc+1), (cr,cc-1)]:
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == val:
                            visited[nr][nc] = True
                            q.append((nr, nc))
                comp_count[val] = comp_count.get(val, 0) + size
    return comp_count

# But I need RECTANGULAR regions
def find_rectangular_regions(grid):
    if not grid or not grid[0]:
        return {}
    h, w = len(grid), len(grid[0])
    regions = {}

    # For each value, find max rectangular area where all cells are that value
    for val in set(v for row in grid for v in row):
        max_rect_area = 0

        for r1 in range(h):
            for c1 in range(w):
                if grid[r1][c1] != val:
                    continue
                # Grow rectangle
                for r2 in range(r1, h):
                    for c2 in range(c1, w):
                        rect = True
                        for r in range(r1, r2+1):
                            for c in range(c1, c2+1):
                                if grid[r][c] != val:
                                    rect = False
                                    break
                            if not rect:
                                break

                        if rect:
                            area = (r2 - r1 + 1) * (c2 - c1 + 1)
                            if area > max_rect_area:
                                max_rect_area = area

        regions[val] = max_rect_area

    return regions

demo_regions = find_rectangular_regions(demo_input)
print("\nDemo input rectangular regions:")
for val, area in sorted(demo_regions.items(), key=lambda x: -x[1]):
    print(f"  Value {val}: {area}")

test_regions = find_rectangular_regions(demo['input'])
print("\nTest input rectangular regions:")
for val, area in sorted(test_regions.items(), key=lambda x: -x[1]):
