import json
from collections import deque

task_id = "task-fde08f04"
program_dir = "/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/held-out-5/play/users/u071/system/state/workspace/programs"

with open(f"{program_dir}/{task_id}.json") as f:
    data = json.load(f)
demo = data[0]
demo_input = demo['input']
demo_output = demo['output']

def find_all_components(grid):
    if not grid or not grid[0]:
        return {}
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    results = {}

    for r in range(h):
        for c in range(w):
            if not visited[r][c]:
                val = grid[r][c]
                q = deque([(r, c)])
                visited[r][c] = True
                size = 0
                cells = []
                while q:
                    cr, cc = q.popleft()
                    size += 1
                    cells.append((cr, cc))
                    for nr, nc in [(cr+1,cc), (cr-1,cc), (cr,cc+1), (cr,cc-1)]:
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == val:
                            visited[nr][nc] = True
                            q.append((nr, nc))
                results[val] = {"size": size, "cells": cells}

    return results

print("Demo input components by value:")
for val, comp in sorted(find_all_components(demo_input).items(), key=lambda x: -x[1]["size"]):
    print(f"  Value {val}: {comp['size']} cells")

largest_val = max(find_all_components(demo_input).items(), key=lambda x: x[1]["size"])[0]
print(f"\nLargest component value: {largest_val}")
print(f"Demo output value: {demo_output[0][0]}")
print(f"Match: {largest_val == demo_output[0][0]}")
